ublication-approved customer outcome. It is not a TechSelectAI Fit Score, Verified Review, Public Review Intelligence score, or vendor marketing claim.</div></section><section class="card" id="problem" data-citation-section><h2>Problem</h2><p><?=nl2br(h($r['problem']))?></p></section><?php if(!empty($r['requirements_text'])):?><section class="card" id="requirements" data-citation-section><h2>Requirements</h2><p><?=nl2br(h($r['requirements_text']))?></p></section><?php endif;?><?php if(!empty($r['options_evaluated'])):?><section class="card" id="options-evaluated" data-citation-section><h2>Options evaluated</h2><p><?=nl2br(h($r['options_evaluated']))?></p></section><?php endif;?><?php if(!empty($r['recommendation'])):?><section class="card" id="recommendation" data-citation-section><h2>Recommendation</h2><p><?=nl2br(h($r['recommendation']))?></p></section><?php endif;?><?php if(!empty($r['rationale'])):?><section class="card" id="rationale" data-citation-section><h2>Why this decision</h2><p><?=nl2br(h($r['rationale']))?></p></section><?php endif;?><?php if(!empty($r['implementation_decision'])):?><section class="card" id="implementation" data-citation-section><h2>Implementation decision</h2><p><?=nl2br(h($r['implementation_decision']))?></p></section><?php endif;?><?php if(!empty($r['measurable_outcome'])):?><section class="card" id="outcome" data-citation-section><h2>Measured outcome</h2><p><?=nl2br(h($r['measurable_outcome']))?></p></section><?php endif;?><section class="card links" id="related" data-citation-section><h2>Related evidence</h2><?php if(!empty($r['product_name'])):?><p>Software: <a href="/software/<?=h($r['product_slug'])?>"><?=h($r['product_name'])?></a></p><?php endif;?><?php if(!empty($r['category_name'])):?><p>Category: <a href="/categories/<?=h($r['category_slug'])?>"><?=h($r['category_name'])?></a></p><?php endif;?><p><a href="/methodology">How TechSelectAI evaluates software</a></p><p><a href="/">Start your own consultation →</a></p></section><